<?php
namespace App\Filament\Pages;
use App\Models\Setting; use App\Services\AdminAudit; use Filament\Forms\Components\{TextInput,Toggle}; use Filament\Notifications\Notification; use Filament\Pages\Page; use Filament\Schemas\Schema;
class SettingsPage extends Page {protected static ?string $slug='settings';protected static ?string $title='Réglages';protected static string|\BackedEnum|null $navigationIcon='heroicon-o-cog-6-tooth';protected static string|\UnitEnum|null $navigationGroup='Système';protected static ?string $navigationLabel='Réglages';protected static ?int $navigationSort=1;protected string $view='filament.pages.settings-page';public ?array $data=[];public function mount():void{$settings=Setting::pluck('value','key');$this->form->fill(['site_name'=>$settings['site_name']['text']??'Top Halal','moderate_reviews'=>$settings['moderate_reviews']['enabled']??true,'moderate_comments'=>$settings['moderate_comments']['enabled']??true,'ai_disclosure_default'=>$settings['ai_disclosure_default']['enabled']??false]);}public function form(Schema $schema):Schema{return $schema->components([TextInput::make('site_name')->required()->maxLength(120),Toggle::make('moderate_reviews')->label('Modérer les avis'),Toggle::make('moderate_comments')->label('Modérer les commentaires'),Toggle::make('ai_disclosure_default')->label('Afficher par défaut la provenance IA')])->statePath('data');}public function save():void{$data=$this->form->getState();foreach($data as $key=>$value)Setting::updateOrCreate(['key'=>$key],['value'=>is_bool($value)?['enabled'=>$value]:['text'=>$value],'group'=>'general']);app(AdminAudit::class)->record('settings.updated','settings',array_keys($data));Notification::make()->title('Réglages enregistrés')->success()->send();}}
